// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initially owner is address(this) (the test contract)
        address alice = address(0x123);
        // Transfer ownership to alice - reference works, bug sets owner to address(0)
        vm.prank(address(this));
        c.transferOwnership(alice);
        // Now try calling owned() as alice
        vm.prank(alice);
        // This will revert on bug because owner is address(0), but succeed on reference
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1111);
        // Initially owner is address(0); transfer ownership to Alice
        vm.prank(address(0));
        c.transferOwnership(alice);
        // Now Alice calls owned(); reference should pass (owner == alice), buggy reverts (owner == address(0))
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // As a non-owner, call owned() - reference should revert, buggy should not
        vm.prank(address(0x1));
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Reference reverts => ok == false; buggy does not revert => ok == true
        assertTrue(ok == false);
    }
}
